                    var ret = new DaoPluginKey();
                    uint count = 0;
                    AVM.ClientGenerator.ABI.ARC4.Types.WireType vPlugin = AVM.ClientGenerator.ABI.ARC4.Types.WireType.FromABIDescription("uint64");
